package com.utegear.controller;
import com.utegear.dto.catalog.*; import com.utegear.service.*; import java.math.BigDecimal; import java.util.List; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class CatalogController { private final CategoryService categories;private final BrandService brands;private final ProductCatalogService products;public CatalogController(CategoryService categories,BrandService brands,ProductCatalogService products){this.categories=categories;this.brands=brands;this.products=products;} @GetMapping("/categories") public List<CategorySummary> categories(){return categories.active();} @GetMapping("/brands") public List<BrandSummary> brands(){return brands.active();} @GetMapping("/products") public ProductDtos.ProductPage products(@RequestParam(required=false)String q,@RequestParam(required=false)Long categoryId,@RequestParam(required=false)Long brandId,@RequestParam(required=false)BigDecimal minPrice,@RequestParam(required=false)BigDecimal maxPrice,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt,desc")String sort){return products.search(q,categoryId,brandId,minPrice,maxPrice,page,size,sort);} @GetMapping("/products/{id}") public ProductDtos.Detail product(@PathVariable Long id){return products.detail(id);} }
